export function validateRubric(r){if(!r||!['concept','grade'].includes(r.mode)||!Array.isArray(r.criteria)||!r.criteria.length||r.criteria.length>20)throw Error('Cadastre de 1 a 20 critérios.');const names=new Set();const criteria=r.criteria.map(c=>{const name=String(c.name||'').trim(),description=String(c.description||'').trim(),min=Number(c.min),max=Number(c.max);if(!name||name.length>200||names.has(name)||description.length>3000)throw Error('Critérios precisam de nomes distintos e descrições válidas.');names.add(name);if(r.mode==='grade'&&(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max<=min))throw Error('Cada critério precisa de início não negativo e final maior que início.');const descriptors={};for(const [key,value] of Object.entries(c.descriptors||{})){if(['__proto__','constructor','prototype'].includes(key)||key.length>60||String(value).length>3000)throw Error('Descrição de nível inválida.');descriptors[key]=String(value);}return {name,description,descriptors,min:r.mode==='grade'?min:0,max:r.mode==='grade'?max:100};});const levels=r.mode==='concept'?(r.levels||[]).map(l=>({name:String(l.name||'').trim(),description:String(l.description||'').trim(),percent:Number(l.percent)})):[];if(r.mode==='concept'&&(!levels.length||levels.length>20||new Set(levels.map(l=>l.name)).size!==levels.length||levels.some(l=>['__proto__','constructor','prototype'].includes(l.name)||!l.name||l.name.length>60||l.description.length>3000||!Number.isFinite(l.percent)||l.percent<0||l.percent>100)))throw Error('Cadastre de 1 a 20 conceitos distintos, com descrição e equivalência de 0 a 100%.');return {mode:r.mode,criteria,levels,levelNames:levels.map(l=>l.name)};}
export function rubricResult(r,values){r=validateRubric(r);if(values.length!==r.criteria.length)throw Error('Corrija todos os critérios.');const criteria=r.criteria.map((c,i)=>{if(values[i]===''||values[i]===undefined)throw Error('Preencha todos os critérios.');if(r.mode==='concept'){const l=r.levels.find(l=>l.name===values[i]);if(!l)throw Error('Selecione um conceito válido.');return {...c,value:l.name,percent:l.percent};}const value=Number(values[i]);if(!Number.isFinite(value)||value<c.min||value>c.max)throw Error('Nota fora da faixa do critério '+c.name);return {...c,value};});const scale=r.mode==='grade'?r.criteria.reduce((n,c)=>n+c.max,0):100,grade=r.mode==='grade'?criteria.reduce((n,c)=>n+c.value,0):criteria.reduce((n,c)=>n+c.percent,0)/criteria.length;return {criteria,grade,scale,percent:grade/scale*100,rubric:r};}
export function trackingMatches(rule,rows){if(rule.type==='concept')return rows.filter(r=>r.grading==='concept'&&r.concept===rule.concept).length>=rule.count;return rows.filter(r=>r.grading==='grade'&&Number.isFinite(r.grade)&&r.scale>0&&r.grade/r.scale*100>=rule.min&&r.grade/r.scale*100<=rule.max).length>=rule.count;}
export function validateTrackingRule(r){if(!r.message?.trim()||r.message.length>200||!/^#[a-fA-F0-9]{6}$/.test(r.color)||!Number.isInteger(r.count)||r.count<1||r.count>100||!['concept','grade'].includes(r.type))throw Error('Informe mensagem, cor e quantidade mínima de resultados.');if(r.type==='concept'&&(!r.concept?.trim()||r.concept.length>60))throw Error('Informe o conceito a acompanhar.');if(r.type==='grade'&&(!Number.isFinite(r.min)||!Number.isFinite(r.max)||r.min<0||r.max>100||r.min>r.max))throw Error('Faixa percentual inválida.');return r;}
